package com.example.complaintmanagement.repository; import com.example.complaintmanagement.entity.Category; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface CategoryRepository extends JpaRepository<Category,Long>{ boolean existsByNameIgnoreCase(String name); Optional<Category> findByNameIgnoreCase(String name); List<Category> findByActiveTrueOrderByNameAsc(); }